#!/usr/bin/env python3
"""Launcher for the IPv6 pipeline compiler / lookup engine.

Builds the optional native helper on first use (a pure python fallback is used
when no compiler is available) and then serves JSON requests, one per line.
"""
import os
import sys


def _here():
    for cand in (globals().get('__file__'), sys.argv[0] if sys.argv else None):
        if cand:
            try:
                return os.path.dirname(os.path.realpath(os.path.abspath(cand)))
            except Exception:
                continue
    return os.getcwd()


def _boot():
    here = _here()
    if here not in sys.path:
        sys.path.insert(0, here)
    try:
        import scamp_pipeline
    except Exception:
        sys.stderr.write('fatal: cannot import scamp_pipeline from %s\n' % here)
        # still answer one line per input line so the transport contract holds
        while True:
            line = sys.stdin.buffer.readline()
            if not line:
                break
            sys.stdout.buffer.write(b'{"status":"invalid"}\n')
            sys.stdout.buffer.flush()
        return 0
    scamp_pipeline.main(here)
    return 0


if __name__ == '__main__':
    sys.exit(_boot())
